EXEC sys.sp_executesql N'/*==============================================================================     2. TRANSACTION LOG SAMPLER ==============================================================================*/  ALTER PROCEDURE dbo.usp_RCA_RunLogSampler       @CaptureRunID bigint     , @DurationMinutes int=3     , @SampleSeconds int=5 AS BEGIN     SET NOCOUNT ON;     SET XACT_ABORT ON;      IF @DurationMinutes < 1         THROW 51800,N''@DurationMinutes must be >= 1.'',1;      IF @SampleSeconds < 1 OR @SampleSeconds > 86399         THROW 51801,N''@SampleSeconds must be between 1 and 86399.'',1;      DECLARE @TargetDatabase sysname,@TargetDatabaseID int;      SELECT @TargetDatabase=TargetDatabase FROM dbo.RCA_CaptureRun WHERE CaptureRunID=@CaptureRunID;      SET @TargetDatabaseID=DB_ID(@TargetDatabase);      IF @TargetDatabaseID IS NULL OR NOT EXISTS (SELECT 1 FROM sys.databases WHERE database_id=@TargetDatabaseID AND state_desc=N''ONLINE'')         THROW 51802,N''Invalid CaptureRunID or target database is unavailable.'',1;      DELETE FROM dbo.RCA_LogSnapshot     WHERE CaptureRunID=@CaptureRunID;      DECLARE           @StartTimeUTC datetime2(3)=SYSUTCDATETIME()         , @StopAt datetime2(3)         , @Delay varchar(8)         , @Samples int=0;      SET @StopAt=DATEADD(minute,@DurationMinutes,@StartTimeUTC);      SET @Delay=         RIGHT(''00''+CONVERT(varchar(2),@SampleSeconds/3600),2)         + '':'' +         RIGHT(''00''+CONVERT(varchar(2),(@SampleSeconds%3600)/60),2)         + '':'' +         RIGHT(''00''+CONVERT(varchar(2),@SampleSeconds%60),2);      CREATE TABLE #LogSpace     (           DatabaseName sysname         , LogSizeMB decimal(19,4)         , LogSpaceUsedPercent decimal(19,4)         , Status int     );      WHILE SYSUTCDATETIME() < @StopAt     BEGIN         TRUNCATE TABLE #LogSpace;          INSERT #LogSpace         EXEC (N''DBCC SQLPERF(LOGSPACE) WITH NO_INFOMSGS;'');          ;WITH Waiters AS         (             SELECT                   r.database_id                 , LogWaiterCount=                     SUM                     (                         CASE                             WHEN r.wait_type IN                                  (                                      N''WRITELOG'',                                      N''LOG_RATE_GOVERNOR'',                                      N''LOG_POOL_CONSUMER'',                                      N''LOG_POOL_CONSUMER_SET''                                  )                                 THEN 1                             ELSE 0                         END                     )                 , WriteLogWaiterCount=                     SUM(CASE WHEN r.wait_type=N''WRITELOG'' THEN 1 ELSE 0 END)                 , LogRateGovernorWaiterCount=                     SUM(CASE WHEN r.wait_type=N''LOG_RATE_GOVERNOR'' THEN 1 ELSE 0 END)             FROM sys.dm_exec_requests AS r             WHERE r.database_id > 0             GROUP BY r.database_id         )         INSERT dbo.RCA_LogSnapshot         (               CaptureRunID             , CaptureTimeUTC             , DatabaseID             , DatabaseName             , RecoveryModelDesc             , FileID             , LogicalFileName             , PhysicalName             , LogSizeMB             , LogSpaceUsedPercent             , NumWrites             , BytesWritten             , IoStallWriteMs             , LogWaiterCount             , WriteLogWaiterCount             , LogRateGovernorWaiterCount         )         SELECT               @CaptureRunID             , SYSUTCDATETIME()             , vfs.database_id             , DB_NAME(vfs.database_id)             , d.recovery_model_desc             , vfs.file_id             , mf.name             , mf.physical_name             , CONVERT(decimal(19,2),ls.LogSizeMB)             , CONVERT(decimal(9,4),ls.LogSpaceUsedPercent)             , vfs.num_of_writes             , vfs.num_of_bytes_written             , vfs.io_stall_write_ms             , ISNULL(w.LogWaiterCount,0)             , ISNULL(w.WriteLogWaiterCount,0)             , ISNULL(w.LogRateGovernorWaiterCount,0)         FROM sys.dm_io_virtual_file_stats(@TargetDatabaseID,NULL) AS vfs         JOIN sys.master_files AS mf           ON mf.database_id=vfs.database_id          AND mf.file_id=vfs.file_id         JOIN sys.databases AS d           ON d.database_id=vfs.database_id         LEFT JOIN #LogSpace AS ls           ON ls.DatabaseName=d.name         LEFT JOIN Waiters AS w           ON w.database_id=vfs.database_id         WHERE mf.type_desc=''LOG'' AND vfs.database_id=@TargetDatabaseID;          SET @Samples+=1;          WAITFOR DELAY @Delay;     END;      SELECT           CaptureRunID=@CaptureRunID         , LogSamplesCaptured=@Samples         , SampleSeconds=@SampleSeconds         , DurationMinutes=@DurationMinutes         , DelayUsed=@Delay; END;';


-- Atomic replacement: dbo.usp_RCA_BuildTransactionLogEvidence
SET @CurrentObject=N'dbo.usp_RCA_BuildTransactionLogEvidence';
EXEC sys.sp_executesql N'/*==============================================================================     5. TRANSACTION LOG DETECTOR      CONSERVATIVE THRESHOLDS     -----------------------     Write latency pressure:         >= 20 ms average log-write latency      Log space pressure:         >= 85% log used for >= 3 samples      Log waiter pressure:         WRITELOG / log-governor waiting for >= 3 samples      Heavy log generation:         >= 256 MB written during observation window      IMPORTANT     ---------     Heavy log generation alone is activity, not a root cause. ==============================================================================*/  ALTER PROCEDURE dbo.usp_RCA_BuildTransactionLogEvidence     @CaptureRunID bigint AS BEGIN     SET NOCOUNT ON;     SET XACT_ABORT ON;      DECLARE @TargetDatabase sysname;      SELECT @TargetDatabase=TargetDatabase FROM dbo.RCA_CaptureRun WHERE CaptureRunID=@CaptureRunID;      IF @TargetDatabase IS NULL         THROW 51810,N''Invalid CaptureRunID.'',1;      DELETE FROM dbo.RCA_TransactionLogEvidence     WHERE CaptureRunID=@CaptureRunID;      ;WITH s AS     (         SELECT               *             , rn_first=                 ROW_NUMBER() OVER                 (                     PARTITION BY CaptureRunID,DatabaseID,FileID                     ORDER BY CaptureTimeUTC,LogSnapshotID                 )             , rn_last=                 ROW_NUMBER() OVER                 (                     PARTITION BY CaptureRunID,DatabaseID,FileID                     ORDER BY CaptureTimeUTC DESC,LogSnapshotID DESC                 )         FROM dbo.RCA_LogSnapshot         WHERE CaptureRunID=@CaptureRunID AND DatabaseName=@TargetDatabase     ),     a AS     (         SELECT               CaptureRunID             , DatabaseID             , DatabaseName=MAX(DatabaseName)             , FileID             , LogicalFileName=MAX(LogicalFileName)             , PhysicalName=MAX(PhysicalName)             , RecoveryModelDesc=MAX(RecoveryModelDesc)              , SampleCount=COUNT(*)              , ObservationSeconds=                 CONVERT                 (                     decimal(19,2),                     DATEDIFF_BIG                     (                         millisecond,                         MIN(CaptureTimeUTC),                         MAX(CaptureTimeUTC)                     ) / 1000.0                 )              , PeakLogSpaceUsedPercent=MAX(LogSpaceUsedPercent)             , AvgLogSpaceUsedPercent=AVG(CONVERT(decimal(19,4),LogSpaceUsedPercent))             , HighLogSpaceSampleCount=                 SUM(CASE WHEN LogSpaceUsedPercent>=85 THEN 1 ELSE 0 END)              , FirstWrites=                 MAX(CASE WHEN rn_first=1 THEN NumWrites END)             , LastWrites=                 MAX(CASE WHEN rn_last=1 THEN NumWrites END)              , FirstBytesWritten=                 MAX(CASE WHEN rn_first=1 THEN BytesWritten END)             , LastBytesWritten=                 MAX(CASE WHEN rn_last=1 THEN BytesWritten END)              , FirstWriteStall=                 MAX(CASE WHEN rn_first=1 THEN IoStallWriteMs END)             , LastWriteStall=                 MAX(CASE WHEN rn_last=1 THEN IoStallWriteMs END)              , PeakLogWaiters=MAX(LogWaiterCount)             , PeakWriteLogWaiters=MAX(WriteLogWaiterCount)             , PeakLogRateGovernorWaiters=MAX(LogRateGovernorWaiterCount)              , LogWaitPressureSampleCount=                 SUM(CASE WHEN LogWaiterCount>0 THEN 1 ELSE 0 END)         FROM s         GROUP BY CaptureRunID,DatabaseID,FileID     ),     c AS     (         SELECT               *             , DeltaWrites=                 CASE                     WHEN LastWrites>=FirstWrites                         THEN LastWrites-FirstWrites                 END              , DeltaWriteMB=                 CONVERT                 (                     decimal(19,2),                     CASE                         WHEN LastBytesWritten>=FirstBytesWritten                             THEN (LastBytesWritten-FirstBytesWritten)/1048576.0                     END                 )              , DeltaWriteStallMs=                 CASE                     WHEN LastWriteStall>=FirstWriteStall                         THEN LastWriteStall-FirstWriteStall                 END         FROM a     )     INSERT dbo.RCA_TransactionLogEvidence     (           CaptureRunID         , DatabaseID         , DatabaseName         , FileID         , LogicalFileName         , PhysicalName         , RecoveryModelDesc         , PressureSubtype         , SampleCount         , ObservationSeconds         , PeakLogSpaceUsedPercent         , AvgLogSpaceUsedPercent         , HighLogSpaceSampleCount         , DeltaWrites         , DeltaWriteMB         , DeltaWriteStallMs         , AvgWriteLatencyMs         , WriteThroughputMBps         , PeakLogWaiters         , PeakWriteLogWaiters         , PeakLogRateGovernorWaiters         , LogWaitPressureSampleCount         , WriteLatencyPressure         , LogSpacePressure         , LogWaitPressure         , HeavyLogGeneration         , RootCauseRole         , Confidence         , EvidenceSummary         , RecommendedAction     )     SELECT           CaptureRunID         , DatabaseID         , DatabaseName         , FileID         , LogicalFileName         , PhysicalName         , RecoveryModelDesc          , PressureSubtype=             CASE                 WHEN                 (                     (DeltaWrites>0 AND DeltaWriteStallMs*1.0/DeltaWrites>=20)                     AND                     (                         HighLogSpaceSampleCount>=3                         OR LogWaitPressureSampleCount>=3                     )                 )                 OR                 (                     HighLogSpaceSampleCount>=3                     AND LogWaitPressureSampleCount>=3                 )                     THEN ''LOG_PRESSURE_MIXED''                  WHEN DeltaWrites>0                  AND DeltaWriteStallMs*1.0/DeltaWrites>=20                     THEN ''LOG_WRITE_LATENCY''                  WHEN HighLogSpaceSampleCount>=3                     THEN ''LOG_SPACE_PRESSURE''                  WHEN LogWaitPressureSampleCount>=3                     THEN ''LOG_WRITE_QUEUE_PRESSURE''                  ELSE ''LOG_ACTIVITY_ONLY''             END          , SampleCount         , ObservationSeconds         , PeakLogSpaceUsedPercent         , AvgLogSpaceUsedPercent         , HighLogSpaceSampleCount         , DeltaWrites         , DeltaWriteMB         , DeltaWriteStallMs          , AvgWriteLatencyMs=             CONVERT             (                 decimal(19,4),                 CASE                     WHEN DeltaWrites>0                         THEN DeltaWriteStallMs*1.0/DeltaWrites                 END             )          , WriteThroughputMBps=             CONVERT             (                 decimal(19,4),                 CASE                     WHEN ObservationSeconds>0                         THEN DeltaWriteMB/ObservationSeconds                 END             )          , PeakLogWaiters         , PeakWriteLogWaiters         , PeakLogRateGovernorWaiters         , LogWaitPressureSampleCount          , WriteLatencyPressure=             CONVERT             (                 bit,                 CASE                     WHEN DeltaWrites>0                      AND DeltaWriteStallMs*1.0/DeltaWrites>=20                         THEN 1                     ELSE 0                 END             )          , LogSpacePressure=             CONVERT(bit,CASE WHEN HighLogSpaceSampleCount>=3 THEN 1 ELSE 0 END)          , LogWaitPressure=             CONVERT(bit,CASE WHEN LogWaitPressureSampleCount>=3 THEN 1 ELSE 0 END)          , HeavyLogGeneration=             CONVERT(bit,CASE WHEN ISNULL(DeltaWriteMB,0)>=256 THEN 1 ELSE 0 END)          , RootCauseRole=             CASE                 WHEN                 (                     (DeltaWrites>0 AND DeltaWriteStallMs*1.0/DeltaWrites>=20)                     OR HighLogSpaceSampleCount>=3                     OR LogWaitPressureSampleCount>=3                 )                     THEN ''PRIMARY''                 ELSE ''CONTRIBUTING''             END          , Confidence=             CASE                 WHEN                 (                     (DeltaWrites>0 AND DeltaWriteStallMs*1.0/DeltaWrites>=20)                     AND                     (                         HighLogSpaceSampleCount>=5                         OR LogWaitPressureSampleCount>=5                     )                 )                 OR                 (                     HighLogSpaceSampleCount>=5                     AND LogWaitPressureSampleCount>=5                 )                     THEN ''HIGH''                  WHEN                 (                     (DeltaWrites>0 AND DeltaWriteStallMs*1.0/DeltaWrites>=20)                     OR HighLogSpaceSampleCount>=3                     OR LogWaitPressureSampleCount>=3                 )                     THEN ''MEDIUM''                  ELSE ''LOW''             END          , EvidenceSummary=             CONVERT             (                 nvarchar(max),                 CONCAT                 (                     ''Database '',DatabaseName,                     ''; log file '',COALESCE(LogicalFileName,N''?''),                     ''; samples='',SampleCount,                     ''; observation='',COALESCE(CONVERT(varchar(30),ObservationSeconds),''NULL''),'' sec'',                     ''; peak log used='',COALESCE(CONVERT(varchar(30),PeakLogSpaceUsedPercent),''NULL''),''%'',                     ''; high-log-space samples='',HighLogSpaceSampleCount,                     ''; writes='',COALESCE(CONVERT(varchar(30),DeltaWrites),''NULL''),                     ''; written='',COALESCE(CONVERT(varchar(30),DeltaWriteMB),''NULL''),'' MB'',                     ''; avg log-write latency='',                     COALESCE                     (                         CONVERT                         (                             varchar(30),                             CASE WHEN DeltaWrites>0 THEN DeltaWriteStallMs*1.0/DeltaWrites END                         ),                         ''NULL''                     ),                     '' ms'',                     ''; peak log waiters='',PeakLogWaiters,                     ''; peak WRITELOG waiters='',PeakWriteLogWaiters,                     ''; peak log-rate-governor waiters='',PeakLogRateGovernorWaiters,                     ''; log-wait pressure samples='',LogWaitPressureSampleCount,                     ''.''                 )             )          , RecommendedAction=             CONVERT             (                 nvarchar(max),                 CASE                     WHEN DeltaWrites>0                      AND DeltaWriteStallMs*1.0/DeltaWrites>=20                     THEN                         ''Investigate transaction-log write latency first. Correlate WRITELOG waits, storage latency, log-file placement, autogrowth events, backup/log-backup activity, and the workload generating log records before changing SQL Server settings.''                      WHEN HighLogSpaceSampleCount>=3                     THEN                         ''Investigate why the transaction log remained heavily utilized. Check active transactions, log reuse wait description, log-backup health, replication/AG dependencies, and autogrowth history before shrinking or growing the log.''                      WHEN LogWaitPressureSampleCount>=3                     THEN                         ''Identify sessions repeatedly waiting on WRITELOG or log-governor resources and correlate them with commit rate, transaction size, log throughput, storage response time, and workload concurrency.''                      ELSE                         ''Transaction-log activity was observed without sufficient latency, wait, or space-pressure evidence. Do not change transaction-log configuration solely from this capture.''                 END             )     FROM c;      SELECT           CaptureRunID=@CaptureRunID         , LogCases=COUNT(*)         , PrimaryCases=SUM(CASE WHEN RootCauseRole=''PRIMARY'' THEN 1 ELSE 0 END)         , HighConfidence=SUM(CASE WHEN Confidence=''HIGH'' THEN 1 ELSE 0 END)         , MediumConfidence=SUM(CASE WHEN Confidence=''MEDIUM'' THEN 1 ELSE 0 END)     FROM dbo.RCA_TransactionLogEvidence     WHERE CaptureRunID=@CaptureRunID; END;';


-- Atomic replacement: dbo.usp_RCA_RunIOSampler
SET @CurrentObject=N'dbo.usp_RCA_RunIOSampler';
EXEC sys.sp_executesql N'ALTER PROCEDURE dbo.usp_RCA_RunIOSampler       @CaptureRunID bigint     , @DurationMinutes int = 3     , @SampleSeconds int = 5 AS BEGIN     SET NOCOUNT ON;     SET XACT_ABORT ON;      IF @DurationMinutes < 1         THROW 51240, N''@DurationMinutes must be >= 1.'', 1;      IF @SampleSeconds < 1 OR @SampleSeconds > 86399         THROW 51241, N''@SampleSeconds must be between 1 and 86399.'', 1;      DECLARE @TargetDatabase sysname,@TargetDatabaseID int;      SELECT @TargetDatabase=TargetDatabase FROM dbo.RCA_CaptureRun WHERE CaptureRunID=@CaptureRunID;      SET @TargetDatabaseID=DB_ID(@TargetDatabase);      IF @TargetDatabaseID IS NULL OR NOT EXISTS (SELECT 1 FROM sys.databases WHERE database_id=@TargetDatabaseID AND state_desc=N''ONLINE'')         THROW 51242,N''Invalid CaptureRunID or target database is unavailable.'',1;      DELETE FROM dbo.RCA_IOFileSnapshot     WHERE CaptureRunID = @CaptureRunID;      DECLARE           @StopAt datetime2(3)         , @Delay varchar(8)         , @Samples int = 0;      SET @StopAt =         DATEADD         (             MINUTE,             @DurationMinutes,             SYSUTCDATETIME()         );      /*         WAITFOR DELAY accepts a character-formatted duration.          Example:             5 seconds  -> 00:00:05            65 seconds  -> 00:01:05     */     SET @Delay =         RIGHT(''00'' + CONVERT(varchar(2), @SampleSeconds / 3600), 2)         + '':'' +         RIGHT         (             ''00'' +             CONVERT             (                 varchar(2),                 (@SampleSeconds % 3600) / 60             ),             2         )         + '':'' +         RIGHT         (             ''00'' +             CONVERT             (                 varchar(2),                 @SampleSeconds % 60             ),             2         );      WHILE SYSUTCDATETIME() < @StopAt     BEGIN          INSERT dbo.RCA_IOFileSnapshot         (               CaptureRunID             , CaptureTimeUTC             , DatabaseID             , DatabaseName             , FileID             , FileTypeDesc             , LogicalFileName             , PhysicalName             , NumReads             , BytesRead             , IoStallReadMs             , NumWrites             , BytesWritten             , IoStallWriteMs             , IoStallMs             , SizeOnDiskBytes         )         SELECT               @CaptureRunID             , SYSUTCDATETIME()             , vfs.database_id             , DB_NAME(vfs.database_id)             , vfs.file_id             , mf.type_desc             , mf.name             , mf.physical_name             , vfs.num_of_reads             , vfs.num_of_bytes_read             , vfs.io_stall_read_ms             , vfs.num_of_writes             , vfs.num_of_bytes_written             , vfs.io_stall_write_ms             , vfs.io_stall             , vfs.size_on_disk_bytes         FROM sys.dm_io_virtual_file_stats(@TargetDatabaseID,NULL) AS vfs         LEFT JOIN sys.master_files AS mf           ON mf.database_id = vfs.database_id          AND mf.file_id = vfs.file_id         WHERE vfs.database_id=@TargetDatabaseID;          SET @Samples += 1;          /*             IMPORTANT:             WAITFOR remains inside the loop.         */         WAITFOR DELAY @Delay;     END;      SELECT           CaptureRunID       = @CaptureRunID         , IOSamplesCaptured  = @Samples         , SampleSeconds      = @SampleSeconds         , DurationMinutes    = @DurationMinutes         , DelayUsed          = @Delay; END;';


-- Atomic replacement: dbo.usp_RCA_BuildIOStorageEvidence
SET @CurrentObject=N'dbo.usp_RCA_BuildIOStorageEvidence';
EXEC sys.sp_executesql N'/*============================================================================== 5. DETECTOR ==============================================================================*/  ALTER PROCEDURE dbo.usp_RCA_BuildIOStorageEvidence     @CaptureRunID bigint AS BEGIN     SET NOCOUNT ON;     SET XACT_ABORT ON;      DECLARE @TargetDatabase sysname;      SELECT @TargetDatabase=TargetDatabase FROM dbo.RCA_CaptureRun WHERE CaptureRunID=@CaptureRunID;      IF @TargetDatabase IS NULL THROW 51710,N''Invalid CaptureRunID.'',1;      DELETE FROM dbo.RCA_IOStorageEvidence     WHERE CaptureRunID=@CaptureRunID;      /* Stronger already-proven causes */     DECLARE @UpstreamCauseCategory varchar(80)=NULL;      IF EXISTS     (         SELECT 1         FROM dbo.RCA_ParameterSensitivePlanEvidence         WHERE CaptureRunID=@CaptureRunID           AND Confidence=''HIGH''     )         SET @UpstreamCauseCategory=''PARAMETER_SENSITIVE_PLAN_REUSE'';      ELSE IF EXISTS     (         SELECT 1         FROM dbo.RCA_StatisticsCardinalityEvidence         WHERE CaptureRunID=@CaptureRunID           AND Confidence=''HIGH''     )         SET @UpstreamCauseCategory=''STATISTICS_CARDINALITY_REGRESSION'';      ELSE IF EXISTS     (         SELECT 1         FROM dbo.RCA_MemorySpillEvidence         WHERE CaptureRunID=@CaptureRunID           AND RootCauseRole=''PRIMARY''           AND Confidence=''HIGH''     )         SET @UpstreamCauseCategory=''MEMORY_GRANT_SPILL'';      ELSE IF EXISTS     (         SELECT 1         FROM dbo.RCA_BlockingEvidence         WHERE CaptureRunID=@CaptureRunID           AND RootCauseRole=''PRIMARY''           AND Confidence=''HIGH''     )         SET @UpstreamCauseCategory=''BLOCKING_WAIT_CHAIN'';      ELSE IF EXISTS     (         SELECT 1         FROM dbo.RCA_CPUSchedulerEvidence         WHERE CaptureRunID=@CaptureRunID           AND RootCauseRole=''PRIMARY''           AND Confidence=''HIGH''     )         SET @UpstreamCauseCategory=''CPU_SCHEDULER_PRESSURE'';       ;WITH Bounded AS     (         SELECT               s.*             , rnFirst =                 ROW_NUMBER() OVER                 (                     PARTITION BY s.CaptureRunID,s.DatabaseID,s.FileID                     ORDER BY s.CaptureTimeUTC                 )             , rnLast =                 ROW_NUMBER() OVER                 (                     PARTITION BY s.CaptureRunID,s.DatabaseID,s.FileID                     ORDER BY s.CaptureTimeUTC DESC                 )             , SampleCount =                 COUNT(*) OVER                 (                     PARTITION BY s.CaptureRunID,s.DatabaseID,s.FileID                 )         FROM dbo.RCA_IOFileSnapshot AS s         WHERE s.CaptureRunID=@CaptureRunID AND s.DatabaseName=@TargetDatabase     ),     FirstLast AS     (         SELECT               CaptureRunID             , DatabaseID             , DatabaseName=MAX(DatabaseName)             , FileID             , LogicalFileName=MAX(LogicalFileName)             , FileTypeDesc=MAX(FileTypeDesc)             , PhysicalName=MAX(PhysicalName)             , SampleCount=MAX(SampleCount)              , FirstTime=MAX(CASE WHEN rnFirst=1 THEN CaptureTimeUTC END)             , LastTime =MAX(CASE WHEN rnLast =1 THEN CaptureTimeUTC END)              , FirstReads=MAX(CASE WHEN rnFirst=1 THEN NumReads END)             , LastReads =MAX(CASE WHEN rnLast =1 THEN NumReads END)             , FirstReadBytes=MAX(CASE WHEN rnFirst=1 THEN BytesRead END)             , LastReadBytes =MAX(CASE WHEN rnLast =1 THEN BytesRead END)             , FirstReadStall=MAX(CASE WHEN rnFirst=1 THEN IoStallReadMs END)             , LastReadStall =MAX(CASE WHEN rnLast =1 THEN IoStallReadMs END)              , FirstWrites=MAX(CASE WHEN rnFirst=1 THEN NumWrites END)             , LastWrites =MAX(CASE WHEN rnLast =1 THEN NumWrites END)             , FirstWriteBytes=MAX(CASE WHEN rnFirst=1 THEN BytesWritten END)             , LastWriteBytes =MAX(CASE WHEN rnLast =1 THEN BytesWritten END)             , FirstWriteStall=MAX(CASE WHEN rnFirst=1 THEN IoStallWriteMs END)             , LastWriteStall =MAX(CASE WHEN rnLast =1 THEN IoStallWriteMs END)         FROM Bounded         GROUP BY               CaptureRunID             , DatabaseID             , FileID     ),     Deltas AS     (         SELECT               *             , DeltaReads = LastReads-FirstReads             , DeltaReadBytes = LastReadBytes-FirstReadBytes             , DeltaReadStallMs = LastReadStall-FirstReadStall             , DeltaWrites = LastWrites-FirstWrites             , DeltaWriteBytes = LastWriteBytes-FirstWriteBytes             , DeltaWriteStallMs = LastWriteStall-FirstWriteStall             , ObservationSeconds =                 CONVERT(decimal(19,2),DATEDIFF_BIG(millisecond,FirstTime,LastTime)/1000.0)         FROM FirstLast     ),     Metrics AS     (         SELECT               *             , AvgReadLatencyMs =                 CONVERT                 (                     decimal(19,4),                     CASE WHEN DeltaReads>0                          THEN (DeltaReadStallMs*1.0)/DeltaReads                     END                 )             , AvgWriteLatencyMs =                 CONVERT                 (                     decimal(19,4),                     CASE WHEN DeltaWrites>0                          THEN (DeltaWriteStallMs*1.0)/DeltaWrites                     END                 )             , DeltaReadMB =                 CONVERT(decimal(19,2),DeltaReadBytes/1048576.0)             , DeltaWriteMB =                 CONVERT(decimal(19,2),DeltaWriteBytes/1048576.0)             , ReadThroughputMBps =                 CONVERT                 (                     decimal(19,4),                     CASE WHEN ObservationSeconds>0                          THEN (DeltaReadBytes/1048576.0)/ObservationSeconds                     END                 )             , WriteThroughputMBps =                 CONVERT                 (                     decimal(19,4),                     CASE WHEN ObservationSeconds>0                          THEN (DeltaWriteBytes/1048576.0)/ObservationSeconds                     END                 )         FROM Deltas     )     INSERT dbo.RCA_IOStorageEvidence     (           CaptureRunID         , DatabaseID         , DatabaseName         , FileID         , LogicalFileName         , FileTypeDesc         , PhysicalName         , SampleCount         , DeltaReads         , DeltaReadMB         , DeltaReadStallMs         , AvgReadLatencyMs         , DeltaWrites         , DeltaWriteMB         , DeltaWriteStallMs         , AvgWriteLatencyMs         , ObservationSeconds         , ReadThroughputMBps         , WriteThroughputMBps         , ReadLatencyPressure         , WriteLatencyPressure         , HeavyReadVolume         , HeavyWriteVolume         , UpstreamCauseCategory         , RootCauseRole         , Confidence         , EvidenceSummary         , RecommendedAction     )     SELECT           @CaptureRunID         , m.DatabaseID         , m.DatabaseName         , m.FileID         , m.LogicalFileName         , m.FileTypeDesc         , m.PhysicalName         , m.SampleCount         , m.DeltaReads         , m.DeltaReadMB         , m.DeltaReadStallMs         , m.AvgReadLatencyMs         , m.DeltaWrites         , m.DeltaWriteMB         , m.DeltaWriteStallMs         , m.AvgWriteLatencyMs         , m.ObservationSeconds         , m.ReadThroughputMBps         , m.WriteThroughputMBps          , ReadLatencyPressure =             CASE                 WHEN ISNULL(m.DeltaReads,0)>=100                  AND ISNULL(m.AvgReadLatencyMs,0)>=20                 THEN 1 ELSE 0             END          , WriteLatencyPressure =             CASE                 WHEN ISNULL(m.DeltaWrites,0)>=100                  AND ISNULL(m.AvgWriteLatencyMs,0)>=20                 THEN 1 ELSE 0             END          , HeavyReadVolume =             CASE WHEN ISNULL(m.DeltaReadMB,0)>=512 THEN 1 ELSE 0 END          , HeavyWriteVolume =             CASE WHEN ISNULL(m.DeltaWriteMB,0)>=512 THEN 1 ELSE 0 END          , @UpstreamCauseCategory          , RootCauseRole =             CASE                 WHEN @UpstreamCauseCategory IS NOT NULL                     THEN ''CONTRIBUTING''                  WHEN                     (                         ISNULL(m.DeltaReads,0)>=100                         AND ISNULL(m.AvgReadLatencyMs,0)>=20                     )                     OR                     (                         ISNULL(m.DeltaWrites,0)>=100                         AND ISNULL(m.AvgWriteLatencyMs,0)>=20                     )                     THEN ''PRIMARY''                  ELSE ''CONTRIBUTING''             END          , Confidence =             CASE                 WHEN                     (                         ISNULL(m.DeltaReads,0)>=100                         AND ISNULL(m.AvgReadLatencyMs,0)>=40                     )                     OR                     (                         ISNULL(m.DeltaWrites,0)>=100                         AND ISNULL(m.AvgWriteLatencyMs,0)>=40                     )                     THEN ''HIGH''                  WHEN                     (                         ISNULL(m.DeltaReads,0)>=100                         AND ISNULL(m.AvgReadLatencyMs,0)>=20                     )                     OR                     (                         ISNULL(m.DeltaWrites,0)>=100                         AND ISNULL(m.AvgWriteLatencyMs,0)>=20                     )                     THEN ''MEDIUM''                  WHEN ISNULL(m.DeltaReadMB,0)>=512                   OR ISNULL(m.DeltaWriteMB,0)>=512                     THEN ''LOW''                  ELSE ''LOW''             END          , EvidenceSummary =             CONCAT             (                 N''File '',COALESCE(m.DatabaseName,N''?''),N''.'',                 COALESCE(m.LogicalFileName,N''?''),                 N'' observed for '',                 COALESCE(CONVERT(varchar(30),m.ObservationSeconds),''NULL''),                 N'' sec. Reads='',COALESCE(CONVERT(varchar(30),m.DeltaReads),''NULL''),                 N'' ('',COALESCE(CONVERT(varchar(30),m.DeltaReadMB),''NULL''),                 N'' MB), avg read latency='',                 COALESCE(CONVERT(varchar(30),m.AvgReadLatencyMs),''NULL''),                 N'' ms, read throughput='',                 COALESCE(CONVERT(varchar(30),m.ReadThroughputMBps),''NULL''),                 N'' MB/s. Writes='',COALESCE(CONVERT(varchar(30),m.DeltaWrites),''NULL''),                 N'' ('',COALESCE(CONVERT(varchar(30),m.DeltaWriteMB),''NULL''),                 N'' MB), avg write latency='',                 COALESCE(CONVERT(varchar(30),m.AvgWriteLatencyMs),''NULL''),                 N'' ms, write throughput='',                 COALESCE(CONVERT(varchar(30),m.WriteThroughputMBps),''NULL''),                 N'' MB/s.''             )          , RecommendedAction =             CASE                 WHEN ISNULL(m.AvgReadLatencyMs,0)>=20                     THEN N''Investigate read latency on the affected database file: correlate high-read queries, file placement, storage tier, host/cache state, and concurrent backup/checkpoint/maintenance activity before changing SQL settings.''                 WHEN ISNULL(m.AvgWriteLatencyMs,0)>=20                     THEN N''Investigate write latency on the affected database file: correlate transaction-log/data-file writes, checkpoint activity, storage tier, host contention, and backup/maintenance activity.''                 ELSE                     N''High I/O volume was observed without strong latency evidence. Correlate the busiest files with query logical/physical reads and confirm whether storage latency was actually user-impacting.''             END     FROM Metrics AS m     WHERE            ISNULL(m.DeltaReads,0)>0         OR ISNULL(m.DeltaWrites,0)>0;      SELECT           CaptureRunID=@CaptureRunID         , IOCases=COUNT(*)         , PrimaryCases=             SUM(CASE WHEN RootCauseRole=''PRIMARY'' THEN 1 ELSE 0 END)         , HighConfidence=             SUM(CASE WHEN Confidence=''HIGH'' THEN 1 ELSE 0 END)         , MediumConfidence=             SUM(CASE WHEN Confidence=''MEDIUM'' THEN 1 ELSE 0 END)     FROM dbo.RCA_IOStorageEvidence     WHERE CaptureRunID=@CaptureRunID; END;';


    -- Verify the new definitions before committing any DDL.
    DECLARE @Gate bit=1;
    IF OBJECT_DEFINITION(OBJECT_ID(N'dbo.usp_RCA_RunLogSampler')) NOT LIKE N'%dm_io_virtual_file_stats(@TargetDatabaseID,NULL)%' SET @Gate=0;
    IF OBJECT_DEFINITION(OBJECT_ID(N'dbo.usp_RCA_RunIOSampler')) NOT LIKE N'%dm_io_virtual_file_stats(@TargetDatabaseID,NULL)%' SET @Gate=0;
    IF OBJECT_DEFINITION(OBJECT_ID(N'dbo.usp_RCA_BuildTransactionLogEvidence')) NOT LIKE N'%DatabaseName=@TargetDatabase%' SET @Gate=0;
    IF OBJECT_DEFINITION(OBJECT_ID(N'dbo.usp_RCA_BuildIOStorageEvidence')) NOT LIKE N'%DatabaseName=@TargetDatabase%' SET @Gate=0;
    IF @Gate=0 THROW 63961,'SCRIPT 111I FAILED: deployment contract did not pass; all DDL will be rolled back.',1;

    COMMIT TRANSACTION;

    SELECT ValidationSection=N'SCRIPT 111I DEPLOYMENT VERDICT',Result=N'PASS',
           Correction=N'TARGET-SCOPED IO AND TRANSACTION-LOG SNAPSHOTS',
           InstalledObjectCount=4,
           AtomicDeployment=N'ALL FOUR OBJECTS COMMITTED',
           SafetyStatement=N'PARSER, XE IMPORTER, STOP, THRESHOLDS, AND ARBITRATION UNCHANGED';
END TRY
BEGIN CATCH
    IF XACT_STATE()<>0 ROLLBACK TRANSACTION;
    DECLARE @Failure nvarchar(2048)=CONCAT(N'SCRIPT 111I v1.4 FAILED atomically at ',COALESCE(@CurrentObject,N'UNKNOWN'),N'; no v1.4 object changes were retained. Original error ',ERROR_NUMBER(),N': ',ERROR_MESSAGE());
    THROW 63961,@Failure,1;
END CATCH;
GO
